    try:
        t = inp.split()
        if len(t) < 2:
            return False
        n, m = int(t[0]), int(t[1])
        if not (1 <= n <= 500 and 1 <= m <= 10**5):
            return False
        if len(t) != 2 + 3 * m:
            return False
        vals = [int(v) for v in t[2:]]
        for i in range(m):
            l, r, x = vals[3 * i], vals[3 * i + 1], vals[3 * i + 2]
            if not (1 <= l <= x <= r <= n):
                return False
        return True
    except Exception:
        return False

def ref(inp):
    t = inp.split()
    n, m = int(t[0]), int(t[1])
    vals = [int(v) for v in t[2:]]
    conds = [(vals[3 * i], vals[3 * i + 1], vals[3 * i + 2]) for i in range(m)]
    count = 0
    for p in permutations(range(1, n + 1)):
        ok = True
        for (l, r, x) in conds:
            seg = p[l - 1:r]
            mx = max(seg)
            if mx == p[x - 1]:
                ok = False
                break
        if ok:
            count += 1
    return str(count % MOD)
